package com.bank.joinunion;

import java.sql.Connection;
import java.sql.ResultSet;
import java.sql.Statement;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

public class StatementDao {
    private static final Logger log = Logger.getLogger(StatementDao.class.getName());
    private final Connection conn;

    public StatementDao(Connection conn) { this.conn = conn; }

    // JOIN: each transaction row WIDENED with holder_name + acct_type.
    public List<String> enrichedTransactions() throws Exception {
        String sql = "SELECT t.txn_id, t.amount, a.holder_name, a.acct_type " +
                     "FROM transactions t JOIN accounts a ON a.id = t.account_id";
        List<String> out = new ArrayList<>();
        try (Statement st = conn.createStatement(); ResultSet rs = st.executeQuery(sql)) {
            while (rs.next()) {
                out.add(rs.getString("txn_id") + " Rs." + rs.getBigDecimal("amount")
                    + " " + rs.getString("holder_name") + " (" + rs.getString("acct_type") + ")");
            }
        }
        log.info(() -> "JOIN (wider rows): " + out);
        return out;
    }

    // UNION ALL: current + archived STACKED into one taller list.
    public List<String> allTransactionsEver() throws Exception {
        String sql = "SELECT txn_id, account_id, amount, txn_date FROM transactions " +
                     "UNION ALL " +
                     "SELECT txn_id, account_id, amount, txn_date FROM transactions_archive " +
                     "ORDER BY txn_date";
        List<String> out = new ArrayList<>();
        try (Statement st = conn.createStatement(); ResultSet rs = st.executeQuery(sql)) {
            while (rs.next()) out.add(rs.getString("txn_id") + " " + rs.getDate("txn_date"));
        }
        log.info(() -> "UNION ALL (taller list): " + out);
        return out;
    }
}
