package com.bank.joinunion;

import java.sql.Connection;
import java.sql.DriverManager;
import java.util.logging.Logger;

public class JoinUnionDemo {
    private static final Logger log = Logger.getLogger(JoinUnionDemo.class.getName());

    public static void main(String[] args) throws Exception {
        try (Connection conn = DriverManager.getConnection(
                "jdbc:postgresql://localhost:5432/bankdb", "bank_app", "secret")) {
            StatementDao dao = new StatementDao(conn);
            dao.enrichedTransactions();  // JOIN adds columns from accounts
            dao.allTransactionsEver();   // UNION ALL adds rows from the archive
            log.info("JOIN widens rows via a match; UNION stacks rows from compatible queries.");
        }
    }
}
